    /// as plain).
    static let pageTitle = OceanTextRole(
        size: 34, weight: .medium, design: .serif, italic: false,
        scale: .native(.largeTitle), leading: 0, tracking: 0,
        sizes: [31, 32, 33, 34, 36, 38, 40, 44, 48, 52, 56, 60])
